INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Lastenheft immer vom Kunden erstellt wird. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Der Kunde definiert die Anforderungen"}, {"text": "Nein", "correct": false, "because": "Kann auch vom Dienstleister mitgestaltet werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich ein Lastenheft für ein IT-Projekt erstelle?', 3, '[{"text": "Klarheit der Anforderungen", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Schnelle Fertigstellung", "correct": false, "because": "Qualität wichtiger"}, {"text": "Designaspekte", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Lastenheft?', 5, '[{"text": "Zieldefinition", "correct": true, "because": "Gibt Projektzweck an"}, {"text": "Funktionale Anforderungen", "correct": true, "because": "Beschreibt Funktionen"}, {"text": "Hardwarezuweisung", "correct": false, "because": "Technische Umsetzung"}, {"text": "Marketingstrategie", "correct": false, "because": "Kein Bestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Lastenheft enthält Kundenanforderungen. b) Es ist immer technisch detailliert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Technik im Pflichtenheft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Lastenheft für Software erstelle?', 4, '[{"text": "Kundenwünsche", "correct": false, "because": "Kern des Dokuments"}, {"text": "Zeitrahmen", "correct": false, "because": "Wichtig für Planung"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Anforderungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Lastenheft technische Lösungen vorschreibt?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Was, nicht Wie"}, {"text": "Ja", "correct": false, "because": "Lösungen im Pflichtenheft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Lastenheft?', 3, '[{"text": "Anforderungen festlegen", "correct": true, "because": "Definiert Projektumfang"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Sekundär"}, {"text": "Hardwarewahl", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte sind im Lastenheft entscheidend?', 5, '[{"text": "Projektziele", "correct": true, "because": "Gibt Richtung vor"}, {"text": "Anforderungskatalog", "correct": true, "because": "Listet Bedarf"}, {"text": "Programmiersprache", "correct": false, "because": "Technische Umsetzung"}, {"text": "Serverstandort", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Lastenheft ist verbindlich. b) Es enthält Implementierungsdetails. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Details im Pflichtenheft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Lastenheft?', 4, '[{"text": "Kundeninput", "correct": false, "because": "Grundlage des Dokuments"}, {"text": "Zeitplan", "correct": false, "because": "Wichtig für Umfang"}, {"text": "Codebeispiele", "correct": true, "because": "Technische Umsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Lastenheft immer vom Auftraggeber zu erstellen?', 2, '[{"text": "Ja", "correct": true, "because": "Kunde legt Anforderungen fest"}, {"text": "Nein", "correct": false, "because": "Kann mit Dienstleister erstellt werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Lastenheft?', 4, '[{"text": "Klarheit für alle", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Vertragliche Basis", "correct": true, "because": "Schützt beide Seiten"}, {"text": "Schnellere Umsetzung", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Lastenheft technische Spezifikationen enthält. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Anforderungen"}, {"text": "Ja", "correct": false, "because": "Technik im Pflichtenheft"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um ein Lastenheft für ein CRM-Projekt zu erstellen?', 3, '[{"text": "Kundenanforderungen", "correct": true, "because": "Definiert Bedarf"}, {"text": "SQL-Skripte", "correct": false, "because": "Technische Umsetzung"}, {"text": "Designvorschläge", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Lastenheft dient der Abstimmung. b) Es ist immer unveränderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Änderungen möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei einem Lastenheft?', 5, '[{"text": "Funktionale Ziele", "correct": true, "because": "Beschreibt Anforderungen"}, {"text": "Nicht-funktionale Anforderungen", "correct": true, "because": "Sichert Qualität"}, {"text": "Programmiersprache", "correct": false, "because": "Technische Entscheidung"}, {"text": "Serverkapazität", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich ein Lastenheft erstelle?', 3, '[{"text": "Projektumfang", "correct": false, "because": "Definiert Grenzen"}, {"text": "Kundenziele", "correct": false, "because": "Grundlage des Dokuments"}, {"text": "Farbschema", "correct": true, "because": "Kein Anforderungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Enthält ein Lastenheft auch die Lösung?', 3, '[{"text": "Nein", "correct": true, "because": "Beschreibt Problem, nicht Lösung"}, {"text": "Ja", "correct": false, "because": "Lösung im Pflichtenheft"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Lastenheft für kleine Projekte überflüssig ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen Klarheit"}, {"text": "Ja", "correct": false, "because": "Immer nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für ein Lastenheft?', 4, '[{"text": "Kundenspezifische Anforderungen", "correct": true, "because": "Kern des Dokuments"}, {"text": "Technische Details", "correct": false, "because": "Nicht enthalten"}, {"text": "Schnelle Fertigstellung", "correct": false, "because": "Qualität zählt"}]');
